56class DaemonControlledResult {
57  static acceptedRequestDidNotComplete(): DaemonExecutorExecutionResult {
58    return this.failure("Cannot answer: accepted daemon request did not complete.\n");
59  }
60 
61  static workspaceCapacityExceeded(): DaemonExecutorExecutionResult {
62    return this.failure("Cannot answer: daemon workspace capacity exceeded.\n");
63  }
64 
65  static responseCapacityExceeded(): DaemonExecutorExecutionResult {
66    return this.failure("Cannot answer: daemon response capacity exceeded.\n");
67  }
68 
69  private static failure(message: string): DaemonExecutorExecutionResult {
70    return { exitCode: 1, output: new DaemonControlledOutput(message) };
71  }
72}
